# Rule: grid split by full separator lines (single color) into blocks. Find the template block (non-uniform), fill it; then replicate its pattern into every other block aligned.
def solve(g):
    H,W=len(g),len(g[0])
    def blks(seps,n):
        bs=[];s=0
        for e in seps:
            if e>s: bs.append((s,e)); s=e+1
        if s<n: bs.append((s,n))
        return bs
    seprows=[r for r in range(H) if len(set(g[r]))==1]
    sepcols=[c for c in range(W) if len({g[r][c] for r in range(H)})==1]
    hb=blks(seprows,H); vb=blks(sepcols,W)
    best=None
    for bi,(r0,r1) in enumerate(hb):
        for bj,(c0,c1) in enumerate(vb):
            blk=[(g[r][c],r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1)]
            cols={v for v,_,_ in blk}
            # uniform if only one distinct color
            uniform = len(cols)==1
            if best is None or not uniform:
                best=(bi,bj,r0,r1,c0,c1)
    pat=[[g[best[2]+i][best[4]+j] for j in range(best[5]-best[4])] for i in range(best[3]-best[2])]
    out=[row[:] for row in g]
    for bi,(r0,r1) in enumerate(hb):
        for bj,(c0,c1) in enumerate(vb):
            for i,row_ in enumerate(range(r0,r1)):
                for j,col_ in enumerate(range(c0,c1)):
                    out[row_][col_]=pat[i][j]
    return out
