    next_sc=[s for s in sc if s>cb]; r_sep=next_sc[0] if next_sc else W
    gt=ra-top_sep-1; gb=bot_sep-rb-1; gl=ca-l_sep-1; gr=r_sep-cb-1
    for a,b in hb:
        for c,d in vb:
            if (a,b)==(ra,rb) or (c,d)==(ca,cb): continue
            nph=min(h,b-a); npw=min(w,d-c)
            cand_r=list(range(0,nph-h+1))
            bestt=min(cand_r,key=lambda t:(t-gt)**2+((b-nph-t)-gb)**2)
            cand_c=list(range(0,npw-w+1))
            bestc=min(cand_c,key=lambda t:(t-gl)**2+((d-npw-t)-gr)**2)
            for i in range(nph):
                for j in range(npw):
                    out[a+bestt+i][c+bestc+j]=pat[i][j]
