def f(g):
    H,W=len(g),len(g[0])
    dom=Counter(x for r in g for x in r).most_common(1)[0][0]
    def count(v): return sum(1 for r in range(H) if all(x==v for x in g[r])) + sum(1 for c in range(W) if all(g[r][c]==v for r in range(H)))
    sepv=max(range(10),key=count)
    sr={r for r in range(H) if len(set(g[r]))==1 and g[r][0]==sepv}
    sc={c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]==sepv}
    def seg(seps,n):
        bds=[-1]+sorted(seps)+[n]; return [(bds[k]+1,bds[k+1]) for k in range(len(bds)-1)]
    hb=seg(sr,H); vb=seg(sc,W)
    best=(-1,0,0,0,0)
    for ra,rb in hb:
        for ca,cb in vb:
            nc=sum(1 for r in range(ra,rb) for c in range(ca,cb) if g[r][c]!=dom)
            if nc>best[0]: best=(nc,ra,rb,ca,cb)
    ra,rb,ca,cb=best[1:]
    minors=[(r-ra,c-ca) for r in range(ra,rb) for c in range(ca,cb) if g[r][c]!=dom]
    rs=[r for r,_ in minors]; cs=[c for _,c in minors]
    h=max(rs)+1; w=max(cs)+1
    pat=[[g[ra+r][ca+c] for c in range(w)] for r in range(h)]
    out=[row[:] for row in g]
    for a,b in hb:
        for c,d in vb:
            if (a,b)==(ra,rb) or (c,d)==(ca,cb): continue
            # bbox bottom-aligned within block: last row of block holds bottom of pattern
            r0 = (b-1)-(h-1)   # == b-h ; clamp if pattern taller than block
            c0 = (d-1)-(w-1)
            r0=min(r0,a+(b-a-h)); c0=min(c0,c+(d-c-w))
            for i in range(h):
                for j in range(w):
                    rr,cc=r0+i,c0+j
                    if 0<=rr<H and 0<=cc<W:
                        out[rr][cc]=pat[i][j]
    return out
